{"content":"'use strict';
// Remap cached tarball entries from https://registry.npmjs.org/... keys to the
// local registry http://127.0.0.1:8070/... keys that npm resolves them to
// (replace-registry-host), so `npm ci --offline` can serve them from cache.
const cacache = require('/usr/local/lib/node_modules/npm/node_modules/cacache');

const CACHE = '/tmp/oc_home/.npm/_cacache';
const PAIRS = [
  ['https://registry.npmjs.org/minimist/-/minimist-1.2.8.tgz', 'http://127.0.0.1:8070/minimist/-/minimist-1.2.8.tgz'],
  ['https://registry.npmjs.org/acorn/-/acorn-8.15.0.tgz', 'http://127.0.0.1:8070/acorn/-/acorn-8.15.0.tgz'],
];

(async () => {
  for (const [oldUrl, newUrl] of PAIRS) {
    const oldKey = `make-fetch-happen:request-cache:${oldUrl}`;
    const newKey = `make-fetch-happen:request-cache:${newUrl}`;
    const info = await cacache.get.info(CACHE, oldKey);
    if (!info) throw new Error(`missing cache entry: ${oldKey}`);
    const metadata = { ...info.metadata, url: newUrl };
    await cacache.index.insert(CACHE, newKey, info.integrity, {
      size: info.size,
      metadata,
    });
    await cacache.rm.entry(CACHE, oldKey);
    const check = await cacache.get.info(CACHE, newKey);
    console.log(
      JSON.stringify({
        key: newKey,
        integrity: check.integrity,
        size: check.size,
        status: check.metadata.status || 200,
      })
    );
  }
})();
